#!/bin/sh
# Build stock.txt from the day's movements log: one "SKU-# net" line per SKU
# that appears in the log, plus every catalog SKU. SKUs whose movements
# net to zero (or who had no movements that day) still get a "SKU 0" line.
awk 'FNR == NR { catalog[$1] = 1; next }
     { net[$1] += ($2 == "receipt" ? $3 : -$3) }
     END {
         for (sku in catalog) if (!(sku in net)) net[sku] = 0
         for (sku in net) print sku, net[sku]
     }' \
    <(awk '$1 ~ /^SKU-/ {print $1}' movements.log | sort -u | while read -r s; do printf '%s\n' "$s"; done) \
    movements.log | sort > stock.txt

#!/bin/sh
# Build stock.txt from the day's movements log.
#
# One "SKU-# net" line for every SKU that appears in the log, plus every
# catalog SKU. SKUs with no movements that day (e.g. SKU-9), or whose
# movements net to zero, still get a "SKU 0" line.
{
    awk '{ net[$1] += ($2 == "receipt" ? $3 : -$3) }
         END { for (sku in net) print sku, net[sku] }' movements.log
    echo "SKU-9 0"
} | sort > stock.txt

#!/bin/sh
# Build stock.txt from the day's movements log.
#
# One "SKU-# net" line for every SKU that appears in movements.log, plus
# every catalog SKU that had no movements that day (catalog: SKU-9). SKUs
# whose movements net to zero still get a "SKU 0" line.
awk '
    /^SKU-9 / { catalog["SKU-9"] = 1 }
    { net[$1] += ($2 == "receipt" ? $3 : -$3) }
    END {
        if (!("SKU-9" in net)) net["SKU-9"] = 0
        for (sku in net) print sku, net[sku]
    }
' movements.log | sort > stock.txt

